for lesson in lessons:
 n=len(lesson['terms'])
 for i,v in enumerate(lesson['terms']):v['distractors']=[(i+1)%n,(i+max(2,n//2))%n]
 assert len(lesson['tasks'])==2 and all(len(x['rows'])==3 and len(x['options'])==3 for x in lesson['tasks'])
 assert len(lesson['quiz'])==6 and sorted(q[2] for q in lesson['quiz'])==[0,0,1,1,2,2]
 assert len(lesson['sections'])==4

def normalise_text(obj):
 if isinstance(obj,str):return obj.replace(chr(8217),chr(39)).replace(chr(8216),chr(39)).replace(chr(8220),chr(34)).replace(chr(8221),chr(34)).replace(chr(8212),', ')
 if isinstance(obj,list):return [normalise_text(v) for v in obj]
 if isinstance(obj,dict):return {k:normalise_text(v) for k,v in obj.items()}
 return obj
lessons=normalise_text(lessons)
isolate_pairs(lessons)
(HERE/'batch5-data.json').write_text(json.dumps(lessons,ensure_ascii=False,indent=2))
print('Authored',len(lessons),'lessons,',sum(len(x['terms']) for x in lessons),'term challenges')
